package com.salarybox.app.ui.login

import androidx.lifecycle.ViewModel
import androidx.lifecycle.ViewModelProvider
import androidx.lifecycle.viewModelScope
import com.salarybox.app.data.local.entity.StaffEntity
import com.salarybox.app.data.model.Role
import com.salarybox.app.data.repository.StaffRepository
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.SharingStarted
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.stateIn
import kotlinx.coroutines.launch

/**
 * Provides the staff list so the login screen can let the user pick which
 * staff member to log in as. Admin login requires no lookup.
 */
class LoginViewModel(private val staffRepository: StaffRepository) : ViewModel() {

    val staffList: StateFlow<List<StaffEntity>> = staffRepository.getAllStaff()
        .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5_000), emptyList())

    private val _error = MutableStateFlow<String?>(null)
    val error: StateFlow<String?> = _error.asStateFlow()

    fun clearError() { _error.value = null }

    fun loginAsAdmin(onSuccess: (Role, Long?) -> Unit) {
        onSuccess(Role.ADMIN, null)
    }

    fun loginAsStaff(staff: StaffEntity?, onSuccess: (Role, Long?) -> Unit) {
        if (staff == null) {
            _error.value = "No staff member selected."
            return
        }
        onSuccess(Role.STAFF, staff.id)
    }
}

class LoginViewModelFactory(private val staffRepository: StaffRepository) : ViewModelProvider.Factory {
    override fun <T : ViewModel> create(modelClass: Class<T>): T {
        if (modelClass.isAssignableFrom(LoginViewModel::class.java)) {
            @Suppress("UNCHECKED_CAST")
            return LoginViewModel(staffRepository) as T
        }
        throw IllegalArgumentException("Unknown ViewModel class")
    }
}

package com.salarybox.app.ui.login

import androidx.compose.foundation.layout.*
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.text.style.TextAlign
import androidx.compose.ui.unit.dp
import androidx.lifecycle.compose.collectAsStateWithLifecycle
import com.salarybox.app.data.model.Role

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun LoginScreen(
    viewModel: LoginViewModel,
    onLoginSuccess: (role: Role, staffId: Long?) -> Unit
) {
    val staffList by viewModel.staffList.collectAsStateWithLifecycle()
    val error by viewModel.error.collectAsStateWithLifecycle()

    // Staff selector state
    var selectedStaff by remember { mutableStateOf<com.salarybox.app.data.local.entity.StaffEntity?>(null) }
    var dropdownExpanded by remember { mutableStateOf(false) }

    // Auto-select the first staff member when the list loads
    LaunchedEffect(staffList) {
        if (selectedStaff == null && staffList.isNotEmpty()) {
            selectedStaff = staffList.first()
        }
    }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .padding(24.dp),
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.Center
    ) {
        Text("SalaryBox", style = MaterialTheme.typography.headlineLarge, fontWeight = FontWeight.Bold)
        Spacer(modifier = Modifier.height(8.dp))
        Text(
            "Face Attendance System",
            style = MaterialTheme.typography.bodyMedium,
            color = MaterialTheme.colorScheme.onSurfaceVariant
        )

        Spacer(modifier = Modifier.height(48.dp))

        // --- Admin Login ---
        Button(
            onClick = { viewModel.loginAsAdmin(onLoginSuccess) },
            modifier = Modifier.fillMaxWidth().height(56.dp)
        ) {
            Text("Login as Admin", style = MaterialTheme.typography.titleMedium)
        }

        Spacer(modifier = Modifier.height(32.dp))

        HorizontalDivider()
        Spacer(modifier = Modifier.height(4.dp))
        Text("or", style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurfaceVariant)
        Spacer(modifier = Modifier.height(4.dp))
        HorizontalDivider()

        Spacer(modifier = Modifier.height(32.dp))

        // --- Staff Login ---
        if (staffList.isEmpty()) {
            Text(
                "No staff members registered yet.\nLogin as Admin first to add staff.",
                style = MaterialTheme.typography.bodyMedium,
                color = MaterialTheme.colorScheme.onSurfaceVariant,
                textAlign = TextAlign.Center
            )
        } else {
            // Staff selector dropdown
            ExposedDropdownMenuBox(
                expanded = dropdownExpanded,
                onExpandedChange = { dropdownExpanded = it }
            ) {
                OutlinedTextField(
                    value = selectedStaff?.let { "${it.name} (${it.employeeId})" } ?: "Select Staff",
                    onValueChange = {},
                    readOnly = true,
                    label = { Text("Staff Member") },
                    trailingIcon = { ExposedDropdownMenuDefaults.TrailingIcon(expanded = dropdownExpanded) },
                    modifier = Modifier.fillMaxWidth().menuAnchor(),
                    colors = ExposedDropdownMenuDefaults.outlinedTextFieldColors()
                )
                ExposedDropdownMenu(
                    expanded = dropdownExpanded,
                    onDismissRequest = { dropdownExpanded = false }
                ) {
                    staffList.forEach { staff ->
                        DropdownMenuItem(
                            text = { Text("${staff.name} (${staff.employeeId})") },
                            onClick = {
                                selectedStaff = staff
                                dropdownExpanded = false
                                viewModel.clearError()
                            }
                        )
                    }
                }
            }

            Spacer(modifier = Modifier.height(16.dp))

            OutlinedButton(
                onClick = { viewModel.loginAsStaff(selectedStaff, onLoginSuccess) },
                modifier = Modifier.fillMaxWidth().height(56.dp),
                enabled = selectedStaff != null
            ) {
                Text("Login as Staff", style = MaterialTheme.typography.titleMedium)
            }
        }

        // Error message
        if (error != null) {
            Spacer(modifier = Modifier.height(12.dp))
            Text(
                text = error!!,
                color = MaterialTheme.colorScheme.error,
                style = MaterialTheme.typography.bodyMedium
            )
        }
    }
}

